var LOGO = "data:image/png;base64,";
var CLASH = "data:image/png;base64,";
var ANON = "data:image/png;base64,";
var MC = "data:image/png;base64,";

// CURSOR
var dot=document.getElementById('dot'),ring=document.getElementById('ring');
var mx=0,my=0,rx=0,ry=0;
document.addEventListener('mousemove',function(e){
  mx=e.clientX;my=e.clientY;
  dot.style.left=mx+'px';dot.style.top=my+'px';
  var dx=(mx/window.innerWidth-.5)*30,dy=(my/window.innerHeight-.5)*30;
  var o1=document.querySelector('.o1'),o2=document.querySelector('.o2'),o3=document.querySelector('.o3');
  if(o1)o1.style.transform='translate('+dx*.8+'px,'+dy*.8+'px)';
  if(o2)o2.style.transform='translate('+(dx*-.6)+'px,'+(dy*-.6)+'px)';
  if(o3)o3.style.transform='translate('+dx*.4+'px,'+(dy*-.4)+'px)';
});
(function aR(){rx+=(mx-rx)*.1;ry+=(my-ry)*.1;ring.style.left=rx+'px';ring.style.top=ry+'px';requestAnimationFrame(aR);})();
document.querySelectorAll('a,button,.chip,.phone,.step,.feat,.tcard').forEach(function(el){
  el.addEventListener('mouseenter',function(){document.body.classList.add('cursor-big');});
  el.addEventListener('mouseleave',function(){document.body.classList.remove('cursor-big');});
});
var nav=document.getElementById('nav');
window.addEventListener('scroll',function(){nav.classList.toggle('s',window.scrollY>50);});
var obs=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('on');obs.unobserve(e.target);}});},{threshold:.08});
document.querySelectorAll('.rv,.rv2,.rv3').forEach(function(el){obs.observe(el);});
var cobs=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){var el=e.target,target=+el.dataset.target,suffix=el.dataset.suffix||'';var t0=performance.now();(function step(now){var p=Math.min((now-t0)/2000,1),ease=1-Math.pow(1-p,3);el.textContent=Math.round(ease*target)+suffix;if(p<1)requestAnimationFrame(step);})(t0);cobs.unobserve(el);}});},{threshold:.5});
document.querySelectorAll('.stat-n[data-target]').forEach(function(el){cobs.observe(el);});
window.addEventListener('scroll',function(){
  document.querySelectorAll('.pm').forEach(function(p){var r=p.getBoundingClientRect(),pr=(r.top+r.height/2)/window.innerHeight-.5;p.style.transform='translateY('+(pr*-16)+'px)';});
  document.querySelectorAll('.ps').forEach(function(p){var r=p.getBoundingClientRect(),pr=(r.top+r.height/2)/window.innerHeight-.5;p.style.transform='translateY('+(pr*-26)+'px)';});
});
document.querySelectorAll('.btn-main,.btn-ghost,.nav-cta,.hero-chat-btn').forEach(function(btn){
  btn.addEventListener('mousemove',function(e){var r=btn.getBoundingClientRect(),dx=(e.clientX-r.left-r.width/2)*.14,dy=(e.clientY-r.top-r.height/2)*.14;btn.style.transform='translate('+dx+'px,'+dy+'px)';});
  btn.addEventListener('mouseleave',function(){btn.style.transform='';});
});
document.querySelectorAll('.step').forEach(function(step){
  step.addEventListener('mousemove',function(e){var r=step.getBoundingClientRect();var shine=step.querySelector('.step-shine');if(shine)shine.style.background='radial-gradient(circle at '+((e.clientX-r.left)/r.width*100)+'% '+((e.clientY-r.top)/r.height*100)+'%,rgba(0,168,255,.08),transparent 50%)';});
});
