// CHAT DEMO
var demos=[
  {user:'Build me a crypto betting game with TON payments and jackpot spin',checks:['Arena logic & round system','TON & Stars payment integration','Jackpot drum animation','Leaderboard & daily rating','Push notifications'],result:{name:'Clash Arena',sub:'\u2713 Live at t.me/arenaclash_bot',img:CLASH}},
  {user:'I want an anonymous chat app with interest-based matching',checks:['Matching algorithm','Anonymous profiles','Real-time messaging','Interest tags & filters'],result:{name:'AnonChat',sub:'\u2713 Live \u00b7 3,200+ users',img:ANON}},
  {user:'Make a Minecraft mining game inside Telegram with TON economy',checks:['Game world & mining','Crafting system (50+ items)','TON economy & item market','Daily leaderboard'],result:{name:'Telegram Miner',sub:'\u2713 Live \u00b7 12,000+ players',img:MC}},
];
var di=0,running=false;
var sleep=function(ms){return new Promise(function(r){setTimeout(r,ms);});};
function addMsg(html,cls){var b=document.getElementById('chatBody'),d=document.createElement('div');d.className='msg '+cls;d.innerHTML=html;b.appendChild(d);requestAnimationFrame(function(){d.classList.add('show');});b.scrollTop=b.scrollHeight;return d;}
function showTyping(){var b=document.getElementById('chatBody'),d=document.createElement('div');d.className='msg bot show';d.innerHTML='<div class="mav"><img src="'+LOGO+'" alt="AF" style="width:28px;height:28px;border-radius:8px;object-fit:cover;"></div><div class="typing"><span></span><span></span><span></span></div>';b.appendChild(d);b.scrollTop=b.scrollHeight;return d;}
async function typeIn(el,txt){el.value='';for(var i=0;i<txt.length;i++){el.value+=txt[i];await sleep(34+Math.random()*20);}}
async function runDemo(d){
  if(running)return;running=true;
  var field=document.getElementById('ciF'),body=document.getElementById('chatBody');
  await sleep(600);await typeIn(field,d.user);await sleep(250);
  addMsg('<div class="mav uav">\u{1F464}</div><div class="bubble">'+d.user+'</div>','user');
  field.value='';await sleep(350);
  var tp=showTyping();await sleep(1000);tp.remove();
  addMsg('<div class="mav"><img src="'+LOGO+'" alt="AF" style="width:28px;height:28px;border-radius:8px;object-fit:cover;"></div><div class="bubble">Got it! Building...<div class="prog-lbl">Working... <span id="pct">0</span>%</div><div class="prog-bar"><div class="prog-fill" id="pf"></div></div><div class="checks" id="chks"></div></div>','bot');
  var pf=document.getElementById('pf'),pct=document.getElementById('pct'),chks=document.getElementById('chks');
  for(var i=0;i<d.checks.length;i++){await sleep(300);var v=Math.round((i+1)/d.checks.length*100);pf.style.width=v+'%';pct.textContent=v;var it=document.createElement('div');it.className='ck';it.innerHTML='<div class="ck-ico"></div><span>'+d.checks[i]+'</span>';chks.appendChild(it);body.scrollTop=body.scrollHeight;await sleep(60);it.classList.add('done');it.querySelector('.ck-ico').textContent='\u2713';await sleep(380);}
  await sleep(400);var tp2=showTyping();await sleep(800);tp2.remove();
  addMsg('<div class="mav"><img src="'+LOGO+'" alt="AF" style="width:28px;height:28px;border-radius:8px;object-fit:cover;"></div><div class="bubble">\uD83C\uDF89 Your app is live!<div class="app-prev"><div class="ap-img"><img src="'+d.result.img+'" alt="'+d.result.name+'" style="width:34px;height:34px;object-fit:cover;border-radius:8px;"></div><div><div class="ap-name">'+d.result.name+'</div><div class="ap-sub">'+d.result.sub+'</div></div><a href="https://t.me/apps_father_bot/app" class="ap-btn" target="_blank">Open \u2192</a></div></div>','bot');
  body.scrollTop=body.scrollHeight;
  await sleep(4500);
  while(body.children.length>1)body.removeChild(body.lastChild);
  running=false;di=(di+1)%demos.length;setTimeout(function(){runDemo(demos[di]);},1000);
}
setTimeout(function(){runDemo(demos[0]);},1200);
// POPUP
function openChat(){document.getElementById('chat-popup').classList.add('open');}
function closeChat(){document.getElementById('chat-popup').classList.remove('open');}
document.getElementById('chat-popup').addEventListener('click',function(e){if(e.target===this)closeChat();});
function cpFill(txt){document.getElementById('cpTa').value=txt;document.getElementById('cpTa').focus();}
var cpChecks=['Analyzing your idea','Generating app structure','Building UI & screens','Integrating TON & Stars payments','Setting up backend logic','Deploying your app'];
var cpSleep=function(ms){return new Promise(function(r){setTimeout(r,ms);});};
function cpAddMsg(html,cls){var b=document.getElementById('cpBody'),d=document.createElement('div');d.className='cp-msg '+cls;d.innerHTML=html;b.appendChild(d);requestAnimationFrame(function(){d.classList.add('show');});b.scrollTop=b.scrollHeight;return d;}
function cpShowTyping(){var b=document.getElementById('cpBody'),d=document.createElement('div');d.className='cp-msg bot show';d.innerHTML='<div class="cp-av"><img src="'+LOGO+'" alt="AF" style="width:28px;height:28px;border-radius:8px;object-fit:cover;"></div><div class="cp-typing"><span></span><span></span><span></span></div>';b.appendChild(d);b.scrollTop=b.scrollHeight;return d;}
async function cpSend(){
  var ta=document.getElementById('cpTa'),idea=ta.value.trim();
  if(!idea){ta.focus();ta.style.borderColor='rgba(255,80,80,.5)';setTimeout(function(){ta.style.borderColor='';},1500);return;}
  document.getElementById('cpInputWrap').style.display='none';
  cpAddMsg('<div class="cp-av uav">\u{1F464}</div><div class="cp-bubble">'+idea+'</div>','user');
  await cpSleep(400);
  var tp=cpShowTyping();await cpSleep(1000);tp.remove();
  cpAddMsg('<div class="cp-av"><img src="'+LOGO+'" alt="AF" style="width:28px;height:28px;border-radius:8px;object-fit:cover;"></div><div class="cp-bubble">Got it! Building your app...<div class="cp-prog-lbl">Working... <span id="cpPct">0</span>%</div><div class="cp-prog-bar"><div class="cp-prog-fill" id="cpPf"></div></div><div class="cp-checks" id="cpCks"></div></div>','bot');
  var pf=document.getElementById('cpPf'),pct=document.getElementById('cpPct'),cks=document.getElementById('cpCks');
  for(var i=0;i<cpChecks.length;i++){await cpSleep(420);var v=Math.round((i+1)/cpChecks.length*100);pf.style.width=v+'%';pct.textContent=v;var it=document.createElement('div');it.className='cp-ck';it.innerHTML='<div class="cp-ck-ico"></div><span>'+cpChecks[i]+'</span>';cks.appendChild(it);document.getElementById('cpBody').scrollTop=9999;await cpSleep(80);it.classList.add('done');it.querySelector('.cp-ck-ico').textContent='\u2713';}
  await cpSleep(500);var tp2=cpShowTyping();await cpSleep(800);tp2.remove();
  cpAddMsg('<div class="cp-av"><img src="'+LOGO+'" alt="AF" style="width:28px;height:28px;border-radius:8px;object-fit:cover;"></div><div class="cp-bubble">\uD83C\uDF89 Done! Your app is ready.<div class="cp-done-wrap"><div class="cp-done-title">\u2705 App built successfully!</div><div class="cp-done-sub">Open Apps Father to launch your real app in 2 minutes</div><a href="https://t.me/apps_father_bot/app" class="cp-done-btn" target="_blank"><svg width="18" height="18" viewBox="0 0 24 24" fill="#fff"><path d="M2 21l21-9L2 3v7l15 2-15 2v7z"/></svg>OPEN APPS FATHER \u2192</a><div class="cp-done-note">Free \u00b7 No code \u00b7 Live in 2 minutes</div></div></div>','bot');
  document.getElementById('cpBody').scrollTop=9999;
}
var cpTa=document.getElementById('cpTa');
if(cpTa)cpTa.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();cpSend();}});
